<!doctype html><html><head><meta charset="utf-8"><style>body{font:11px DejaVu Sans,sans-serif;color:#18231d}h1,h2{color:#176344}h1{font-size:19px}h2{font-size:14px;margin:18px 0 6px}.summary{width:100%;border-collapse:collapse;margin:8px 0 16px}.summary td{border-bottom:1px solid #ddd;padding:6px}.summary td:last-child{text-align:right;font-weight:bold}table.data{width:100%;border-collapse:collapse;margin-top:8px}table.data th,table.data td{border-bottom:1px solid #ddd;padding:6px;text-align:left}table.data th:last-child,table.data td:last-child{text-align:right}.muted{color:#68736d}.total{font-weight:bold}</style></head><body>
